int main() {
    int t, n, x;
    if (!(cin >> t)) return 0;
    while (t--) {
        cin >> n >> x;
        int ans = 0;
        for (int i = 1; i <= n; i++) {
            ans += 1;        // 基础能量
            if (i % x == 0) {
                ans += 1;    // 额外奖励
            }
        }
        cout << ans << endl;
    }
    return 0;
}

